/* Superheroes set additions — cards appended after hero.js.
   (hero.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'hero.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('hero');
  if (!S) return;
  var extra = [{"name":"Absorbing Man","rarity":"common","id":"absorbing-man","subtitle":"Villain","details":"Carl 'Crusher' Creel debuted in Journey into Mystery #114 in 1965, gaining from a potion of Loki's the power to become anything he touches.","image":"https://upload.wikimedia.org/wikipedia/en/2/2e/Absorbing_Man.png"},{"name":"America Chavez","rarity":"common","id":"america-chavez","subtitle":"Hero","details":"America Chavez debuted in Vengeance #1 in 2011, punching star-shaped portals between dimensions as the powerhouse known as Miss America.","image":"https://upload.wikimedia.org/wikipedia/en/4/46/America_Chavez_%28Design_from_2024%29.webp"},{"name":"Angel","rarity":"common","id":"angel","subtitle":"Hero","details":"Warren Worthington III debuted in X-Men #1 in 1963, a wealthy mutant born with great white wings, later twisted by Apocalypse into Archangel.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/c/cd/Warren_Worthington_III_%28Earth-616%29_from_Official_Handbook_of_the_Marvel_Universe_Vol_2_1_0001.jpg/revision/latest?cb=20111222152916"},{"name":"Annihilus","rarity":"common","id":"annihilus","subtitle":"Villain","details":"Annihilus debuted in Fantastic Four Annual #6 in 1968, the insectoid tyrant of the Negative Zone, guarding his life-prolonging Cosmic Control Rod.","image":"https://upload.wikimedia.org/wikipedia/en/3/30/Annihilus.png"},{"name":"Beetle","rarity":"common","id":"beetle","subtitle":"Villain","details":"Abner Jenkins debuted in Strange Tales #123 in 1964, a mechanic who built the Beetle armor, then reformed to fly with the Thunderbolts as Mach-1.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/0/07/Abner_Jenkins_%28Earth-616%29_from_Thunderbolts_Vol_4_4_001.png/revision/latest?cb=20160901025546"},{"name":"Betty Ross","rarity":"common","id":"betty-ross","subtitle":"Supporting","details":"Betty Ross debuted in The Incredible Hulk #1 in 1962, the general's daughter and the great love Bruce Banner's transformations keep tearing him from.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/1/1c/Elizabeth_Ross_%28Earth-616%29_from_Incredible_Hulk_Vol_1_427_001.jpg/revision/latest?cb=20210214205527"},{"name":"Blade","rarity":"common","id":"blade","subtitle":"Hero","details":"Eric Brooks debuted in Tomb of Dracula #10 in 1973, a half-vampire Daywalker immune to sunlight who hunts the vampires that prey on humanity.","image":"https://upload.wikimedia.org/wikipedia/en/3/37/Blade_%28Marvel_Comics%29.png"},{"name":"Blob","rarity":"common","id":"blob","subtitle":"Villain","details":"Fred J. Dukes debuted in X-Men #3 in 1964, a carnival strongman whose immense, rubbery mass makes him literally immovable once he plants his feet.","image":"https://upload.wikimedia.org/wikipedia/en/7/7a/Blob_%28Frederick_J._%22Fred%22_Dukes%29.png"},{"name":"Chameleon","rarity":"common","id":"chameleon","subtitle":"Villain","details":"Dmitri Smerdyakov debuted in The Amazing Spider-Man #1 in 1963, the first villain Spider-Man faced in his series and a master of masks and mimicry.","image":"https://upload.wikimedia.org/wikipedia/en/4/43/Dmitri_Smerdyakov_as_The_Chameleon_%282021%29.webp"},{"name":"Crimson Dynamo","rarity":"common","id":"crimson-dynamo","subtitle":"Villain","details":"The Crimson Dynamo armor debuted in Tales of Suspense #46 in 1963, the Soviet Union's red answer to Iron Man, worn by a succession of pilots.","image":"https://upload.wikimedia.org/wikipedia/en/d/de/Crimson_Dynamo_002.jpg"},{"name":"Crossbones","rarity":"common","id":"crossbones","subtitle":"Villain","details":"Brock Rumlow, the brutal mercenary called Crossbones, is the Red Skull's most loyal enforcer and is a recurring thorn in Captain America's side.","image":"https://upload.wikimedia.org/wikipedia/en/1/17/Crossbones_%28Marvel_Comics%29.jpeg"},{"name":"Daily Bugle","rarity":"common","id":"daily-bugle","subtitle":"Location","details":"New York's loudest tabloid, published by J. Jonah Jameson, where Peter Parker sold photos of Spider-Man to the very paper calling him a menace.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/c/c5/Daily_Bugle_Building_from_Official_Handbook_of_the_Marvel_Universe_Vol_1_3_0001.jpg/revision/latest?cb=20060330114424"},{"name":"Dazzler","rarity":"common","id":"dazzler","subtitle":"Hero","details":"Alison Blaire debuted in Uncanny X-Men #130 in 1980, a disco-singing mutant who converts sound into dazzling, concussive light.","image":"https://upload.wikimedia.org/wikipedia/en/b/b8/Dazzler_%28Alison_%22Ali%22_Blaire%29.png"},{"name":"Echo","rarity":"common","id":"echo","subtitle":"Hero","details":"Maya Lopez debuted in Daredevil #9 in 1999, a deaf martial artist with photographic reflexes who can copy any move she sees performed once.","image":"https://upload.wikimedia.org/wikipedia/en/3/35/Maya_Lopez_as_Echo_%282024_Design%29.webp"},{"name":"Ego the Living Planet","rarity":"common","id":"ego-the-living-planet","subtitle":"Villain","details":"Ego debuted in Thor #132 in 1966, a planet-sized organism with a face, a temper and the power to reshape its own surface at will.","image":"https://upload.wikimedia.org/wikipedia/en/8/8c/Egoplanet.PNG"},{"name":"Flash Thompson","rarity":"common","id":"flash-thompson","subtitle":"Supporting","details":"Flash Thompson debuted in Amazing Fantasy #15 in 1962 as Peter Parker's tormentor and Spider-Man's biggest fan, who grew into a hero himself.","image":"https://upload.wikimedia.org/wikipedia/en/9/95/Flash_Thompson.png"},{"name":"Foggy Nelson","rarity":"common","id":"foggy-nelson","subtitle":"Supporting","details":"Franklin 'Foggy' Nelson debuted in Daredevil #1 in 1964, Matt Murdock's college roommate, law partner and the human heart of Nelson and Murdock.","image":"https://upload.wikimedia.org/wikipedia/en/9/92/Foggy_Nelson.png"},{"name":"Ghost","rarity":"common","id":"ghost","subtitle":"Villain","details":"The unnamed corporate saboteur called Ghost debuted in Iron Man #219 in 1987, wearing a suit that turns him intangible and invisible at will.","image":"https://upload.wikimedia.org/wikipedia/en/9/91/Ghost_%28Marvel_character%29.jpg"},{"name":"Grandmaster","rarity":"common","id":"grandmaster","subtitle":"Villain","details":"The Grandmaster debuted in The Avengers #69 in 1969, an immortal Elder of the Universe who treats heroes as pieces in cosmic games of chance.","image":"https://upload.wikimedia.org/wikipedia/en/5/58/Thunderbolts_Vol_1_102_Textless.jpg"},{"name":"Gwen Stacy","rarity":"common","id":"gwen-stacy","subtitle":"Supporting","details":"Gwen Stacy, Peter Parker's first serious love, died in The Amazing Spider-Man #121 in 1973, a loss that changed superhero comics forever.","image":"https://upload.wikimedia.org/wikipedia/en/5/5b/Gwen_Stacy_%28circa_2020%29.png"},{"name":"Harry Osborn","rarity":"common","id":"harry-osborn","subtitle":"Supporting","details":"Harry Osborn debuted in The Amazing Spider-Man #31 in 1965, Peter Parker's best friend, forever in the shadow of his father Norman, the Green Goblin.","image":"https://upload.wikimedia.org/wikipedia/en/1/17/Harry_Osborn.png"},{"name":"Havok","rarity":"common","id":"havok","subtitle":"Hero","details":"Alex Summers debuted in X-Men #54 in 1969, Cyclops's younger brother, absorbing cosmic energy and blasting it back in devastating rings of plasma.","image":"https://upload.wikimedia.org/wikipedia/en/9/9f/Havok_%28Alex_Summers%29.png"},{"name":"Hawkeye (Kate Bishop)","rarity":"common","id":"hawkeye-kate-bishop","subtitle":"Hero","details":"Kate Bishop debuted in Young Avengers #1 in 2005, a wealthy archer with no powers who took up the Hawkeye name when Clint Barton was gone.","image":"https://upload.wikimedia.org/wikipedia/en/1/1f/Hawkeye_%28Kate_Bishop%29.png"},{"name":"Hell's Kitchen","rarity":"common","id":"hells-kitchen","subtitle":"Location","details":"The gritty Manhattan neighborhood Matt Murdock grew up in and defends as Daredevil, its tenements and docks a battleground for the Kingpin's empire.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/a/aa/Hell%27s_Kitchen_from_Dark_Reign_The_List_-_Daredevil_Vol_1_1_001.jpg/revision/latest?cb=20091211140726"},{"name":"Hobgoblin","rarity":"common","id":"hobgoblin","subtitle":"Villain","details":"The Hobgoblin debuted in The Amazing Spider-Man #238 in 1983, a mystery man who stole the Green Goblin's gear and kept his identity secret for years.","image":"https://upload.wikimedia.org/wikipedia/en/8/89/Hobgoblin_%28Marvel_Comics%29.png"},{"name":"Hydro-Man","rarity":"common","id":"hydro-man","subtitle":"Villain","details":"Morris Bench debuted in The Amazing Spider-Man #212 in 1981, a sailor knocked into experimental waters and transformed into living, surging water.","image":"https://upload.wikimedia.org/wikipedia/en/b/b9/Hydro-Man_%28Morris_%27Morrie%27_Bench%29.png"},{"name":"Illuminati","rarity":"common","id":"illuminati","subtitle":"Team","details":"The Illuminati is a secret cabal of Marvel's greatest minds, Iron Man, Reed Richards and Doctor Strange, steering world events from the shadows.","image":"https://upload.wikimedia.org/wikipedia/en/4/46/NEWAVNIL001.jpg"},{"name":"Iron Fist","rarity":"common","id":"iron-fist","subtitle":"Hero","details":"Danny Rand debuted in Marvel Premiere #15 in 1974, heir to a fortune who trained in K'un-Lun to channel his chi into an unstoppable iron fist.","image":"https://upload.wikimedia.org/wikipedia/en/0/00/Iron_Fist_%28Danny_Rand%29.jpg"},{"name":"Iron Monger","rarity":"common","id":"iron-monger","subtitle":"Villain","details":"Obadiah Stane, the business rival who maneuvered to seize Stark's company, built the towering Iron Monger armor to crush Iron Man personally.","image":"https://upload.wikimedia.org/wikipedia/en/a/a8/Iron_Monger_%28Obadiah_Stane%29.png"},{"name":"Ironheart","rarity":"common","id":"ironheart","subtitle":"Hero","details":"Riri Williams, a teenage engineering genius at MIT, built her own suit of powered armor in her dorm room and took to the skies as Ironheart.","image":"https://upload.wikimedia.org/wikipedia/en/a/a8/2020_Ironheart_1.jpg"},{"name":"Jubilee","rarity":"common","id":"jubilee","subtitle":"Hero","details":"Jubilation Lee debuted in Uncanny X-Men #244 in 1989, a mall-dwelling runaway whose mutant 'fireworks' of plasma energy lit up the X-Men's ranks.","image":"https://upload.wikimedia.org/wikipedia/en/d/d6/X-Men_-_Jubilee_Cover.webp"},{"name":"Karen Page","rarity":"common","id":"karen-page","subtitle":"Supporting","details":"Karen Page debuted in Daredevil #1 in 1964 as the secretary of Nelson and Murdock, becoming Matt Murdock's first great love and a crusading reporter.","image":"https://upload.wikimedia.org/wikipedia/en/0/08/Karen_Page_%28Marvel_Comics_character%29.png"},{"name":"Kitty Pryde","rarity":"common","id":"kitty-pryde","subtitle":"Hero","details":"Kitty Pryde debuted in Uncanny X-Men #129 in 1980, joining the X-Men at thirteen with the power to phase through solid matter.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/1/16/Exceptional_X-Men_Vol_1_10_Pride_Variant_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Klaw","rarity":"common","id":"klaw","subtitle":"Villain","details":"Ulysses Klaw debuted in Fantastic Four #53 in 1966, a physicist who converted his own body into living sound and projects solid sonic constructs.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/1/10/Ulysses_Klaw_%28Earth-616%29_from_Superior_Carnage_Vol_1_1_001.jpg/revision/latest?cb=20130718233151"},{"name":"Knowhere","rarity":"common","id":"knowhere","subtitle":"Location","details":"A mining colony and spaceport built inside the severed head of an ancient Celestial, floating at the edge of known space beyond any law.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/e/ee/Knowhere_from_Infinity_Countdown_Vol_1_4_001.jpg/revision/latest/scale-to-width-down/512"},{"name":"Lady Deathstrike","rarity":"common","id":"lady-deathstrike","subtitle":"Villain","details":"Yuriko Oyama, consumed by vengeance for her father's stolen adamantium research, became Lady Deathstrike, her fingers tipped with adamantium talons.","image":"https://upload.wikimedia.org/wikipedia/en/7/7e/LadyArtistsStrike.jpg"},{"name":"Latveria","rarity":"common","id":"latveria","subtitle":"Location","details":"A small Eastern European kingdom ruled absolutely by Doctor Doom from Castle Doom in Doomstadt, prosperous, orderly and watched at all times.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/a/ad/Latveria_from_Invincible_Iron_Man_Vol_3_1_001.jpg/revision/latest/scale-to-width-down/900?cb=20160518214741"},{"name":"M'Baku","rarity":"common","id":"mbaku","subtitle":"Villain","details":"M'Baku debuted in The Avengers #62 in 1969, leader of Wakanda's Jabari tribe and the mighty Man-Ape, who has repeatedly challenged the Black Panther.","image":"https://upload.wikimedia.org/wikipedia/en/6/63/Manape.png"},{"name":"Mantis","rarity":"common","id":"mantis","subtitle":"Hero","details":"Mantis debuted in The Avengers #112 in 1973, an empath and martial artist whose path led from the Avengers to the Guardians of the Galaxy.","image":"https://upload.wikimedia.org/wikipedia/en/8/8c/Mantismadona.jpg"},{"name":"Midnight Sons","rarity":"common","id":"midnight-sons","subtitle":"Team","details":"The Midnight Sons unite Marvel's supernatural heroes, Ghost Rider, Blade and Morbius among them, against occult threats no one else will face.","image":"https://upload.wikimedia.org/wikipedia/en/4/45/Doctor_Strange_Damnation_Vol_1_2_Smallwood_Connecting_Variant_Textless.png"},{"name":"Mockingbird","rarity":"common","id":"mockingbird","subtitle":"Hero","details":"Bobbi Morse is a brilliant biologist and elite S.H.I.E.L.D. agent whose battle staves and dry wit made her a mainstay of the Avengers' ranks.","image":"https://upload.wikimedia.org/wikipedia/en/0/04/Mockingbird_%28Marvel_Comics%29.png"},{"name":"Morbius","rarity":"common","id":"morbius","subtitle":"Anti-Hero","details":"Dr. Michael Morbius debuted in The Amazing Spider-Man #101 in 1971, a scientist whose cure for his own blood disease made him a living vampire.","image":"https://upload.wikimedia.org/wikipedia/en/7/7f/Michael_Morbius.png"},{"name":"Nova","rarity":"common","id":"nova","subtitle":"Hero","details":"Richard Rider debuted in Nova #1 in 1976, a Queens teenager chosen by a dying alien centurion to carry the power of the Nova Corps.","image":"https://upload.wikimedia.org/wikipedia/en/2/26/Nova1adigranov.jpg"},{"name":"Omega Red","rarity":"common","id":"omega-red","subtitle":"Villain","details":"Arkady Rossovich debuted in X-Men #4 in 1992, a Soviet super-soldier with carbonadium tentacles and a mutant 'death factor' that drains life itself.","image":"https://upload.wikimedia.org/wikipedia/en/1/10/Omega_Red.png"},{"name":"Pyro","rarity":"common","id":"pyro","subtitle":"Villain","details":"St. John Allerdyce debuted in Uncanny X-Men #141 in 1981, a mutant who can shape and control fire but cannot create it, himself.","image":"https://upload.wikimedia.org/wikipedia/en/2/2a/Pyro_%28St._John_Allerdyce%29.png"},{"name":"Quicksilver","rarity":"common","id":"quicksilver","subtitle":"Hero","details":"Pietro Maximoff debuted in X-Men #4 in 1964, a super-speedster who first ran with his twin sister Wanda in Magneto's Brotherhood of Evil Mutants.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/8/80/Pietro_Maximoff_%28Earth-616%29_from_Scarlet_Witch_%26_Quicksilver_Vol_1_3_Cover_001.jpg/revision/latest/scale-to-width-down/1000?cb=20250517010915"},{"name":"Ronan the Accuser","rarity":"common","id":"ronan-the-accuser","subtitle":"Villain","details":"Ronan debuted in Fantastic Four #65 in 1967, the Kree Empire's supreme Accuser, judging entire worlds with his hammer, the Universal Weapon.","image":"https://upload.wikimedia.org/wikipedia/en/f/f2/Ronan_the_Accuser_design.jpg"},{"name":"Sanctum Sanctorum","rarity":"common","id":"sanctum-sanctorum","subtitle":"Location","details":"Doctor Strange's home at 177A Bleecker Street in Greenwich Village, a townhouse of mystical wards and impossible rooms guarding powerful relics.","image":"https://upload.wikimedia.org/wikipedia/en/7/74/Sanctum_Sanctorum.jpg"},{"name":"Savage Land","rarity":"common","id":"savage-land","subtitle":"Location","details":"A prehistoric jungle hidden in Antarctica, kept warm by ancient machinery, where dinosaurs still roam and the hero Ka-Zar watches over the wilds.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/6/62/Savage_Land_from_Rogue_The_Savage_Land_Vol_1_1_001.jpg/revision/latest/scale-to-width-down/1000?cb=20250120225133"},{"name":"Scorpion","rarity":"common","id":"scorpion","subtitle":"Villain","details":"Mac Gargan debuted in The Amazing Spider-Man #20 in 1964, a private eye mutated by J. Jonah Jameson into the Scorpion to destroy Spider-Man.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/Scorpion_%28Mac_Gargan%29.png"},{"name":"Shang-Chi","rarity":"common","id":"shang-chi","subtitle":"Hero","details":"Shang-Chi debuted in Special Marvel Edition #15 in 1973, raised to be an assassin by his father and famed as the Master of Kung Fu.","image":"https://upload.wikimedia.org/wikipedia/en/6/62/Shang-Chi_Vol_1_%2C1.jpg"},{"name":"Shocker","rarity":"common","id":"shocker","subtitle":"Villain","details":"Herman Schultz debuted in The Amazing Spider-Man #46 in 1967, a career criminal whose homemade gauntlets fire crushing blasts of compressed air.","image":"https://upload.wikimedia.org/wikipedia/en/7/78/Shocker_%28Herman_Schultz%29.jpg"},{"name":"Silk","rarity":"common","id":"silk","subtitle":"Hero","details":"Cindy Moon was bitten by the same radioactive spider as Peter Parker, gaining a powerful silk-sense and organic webbing from her fingertips.","image":"https://upload.wikimedia.org/wikipedia/en/9/90/Silk%2C_Vol._3%2C_no._1_textless_cover_%28variant%29.png"},{"name":"Silver Sable","rarity":"common","id":"silver-sable","subtitle":"Anti-Hero","details":"Silver Sablinova debuted in The Amazing Spider-Man #265 in 1985, a mercenary who leads the Wild Pack hunting war criminals across the globe.","image":"https://upload.wikimedia.org/wikipedia/en/d/d6/Silver_Sable_%28Silver_Sablinova_-_circa_2017%29.png"},{"name":"Silver Samurai","rarity":"common","id":"silver-samurai","subtitle":"Villain","details":"Keniuchio Harada debuted in Daredevil #111 in 1974, a mutant who channels energy through his katana, cutting through nearly anything.","image":"https://upload.wikimedia.org/wikipedia/en/2/2e/Silversumor.jpg"},{"name":"Spider-Gwen","rarity":"common","id":"spider-gwen","subtitle":"Hero","details":"On Earth-65, it was Gwen Stacy who got the spider bite. She debuted in Edge of Spider-Verse #2 in 2014, drumming by night and web-swinging by day.","image":"https://upload.wikimedia.org/wikipedia/en/4/42/Spider-Gwen_Vol_1_1.jpg"},{"name":"Spider-Woman","rarity":"common","id":"spider-woman","subtitle":"Hero","details":"Jessica Drew debuted in Marvel Spotlight #32 in 1977, a former spy whose bioelectric 'venom blasts' and pheromones make her a formidable Spider-Woman.","image":"https://upload.wikimedia.org/wikipedia/en/6/61/Spider-Woman_%28Jessica_Drew_-_original_costume_-_circa_2020%29.png"},{"name":"Squirrel Girl","rarity":"common","id":"squirrel-girl","subtitle":"Hero","details":"Doreen Green debuted in Marvel Super-Heroes #8 in 1992, commanding squirrels and improbably defeating villains far above her weight class.","image":"https://upload.wikimedia.org/wikipedia/en/e/e2/Unbeatable_Squirrel_Girl.jpg"},{"name":"Super-Skrull","rarity":"common","id":"super-skrull","subtitle":"Villain","details":"Kl'rt debuted in Fantastic Four #18 in 1963, a Skrull warrior engineered with the combined powers of all four members of the Fantastic Four.","image":"https://upload.wikimedia.org/wikipedia/en/8/87/Super_Skrull.jpg"},{"name":"The Collector","rarity":"common","id":"the-collector","subtitle":"Villain","details":"Taneleer Tivan debuted in The Avengers #28 in 1966, an Elder of the Universe who obsessively hoards the rarest species and artifacts in existence.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/1/10/Taneleer_Tivan_%28Earth-616%29_from_Legendary_Star-Lord_Vol_1_12_001.jpg/revision/latest/scale-to-width-down/1000?cb=20210718232412"},{"name":"Titania","rarity":"common","id":"titania","subtitle":"Villain","details":"Mary MacPherran debuted in Secret Wars #3 in 1984, a slight Denver woman granted immense strength on Battleworld, becoming She-Hulk's fiercest rival.","image":"https://upload.wikimedia.org/wikipedia/en/9/9f/Mary_MacPherran_as_Titania_%282018_Design%29.webp"},{"name":"Toad","rarity":"common","id":"toad","subtitle":"Villain","details":"Mortimer Toynbee debuted in X-Men #4 in 1964, a leaping, long-tongued mutant who served Magneto's Brotherhood despite years of ridicule.","image":"https://upload.wikimedia.org/wikipedia/en/9/9d/Toad_%28Mortimer_Toynbee_%29.png"},{"name":"Tombstone","rarity":"common","id":"tombstone","subtitle":"Villain","details":"Lonnie Lincoln debuted in Web of Spider-Man #36 in 1988, an albino crime boss with filed teeth and skin nearly as hard as the stone he's named for.","image":"https://upload.wikimedia.org/wikipedia/en/7/79/Tombstone_%28Marvel_Comics_character%29.png"},{"name":"West Coast Avengers","rarity":"common","id":"west-coast-avengers","subtitle":"Team","details":"Hawkeye founded the West Coast Avengers in 1984, the Avengers' Los Angeles branch, proving Earth's Mightiest Heroes could guard two coasts at once.","image":"https://upload.wikimedia.org/wikipedia/en/5/5c/West_Coast_Avengers_vol._2%2C_no._1_%28cover_art%29.jpg"},{"name":"Whiplash","rarity":"common","id":"whiplash","subtitle":"Villain","details":"Whiplash wields electrified whips and powered armor in a long vendetta against Iron Man, turning cutting-edge tech into instruments of revenge.","image":"https://upload.wikimedia.org/wikipedia/en/b/b8/Whiplash_IV.jpg"},{"name":"Wong","rarity":"common","id":"wong","subtitle":"Supporting","details":"Wong debuted in Strange Tales #110 in 1963, the steadfast attendant, martial artist and librarian who keeps Doctor Strange's Sanctum and secrets.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/b/b8/Strange_Academy_Vol_1_15_Character_Spotlight_Variant_Textless.jpg/revision/latest/scale-to-width-down/1000?cb=20221006161810"},{"name":"Yellowjacket","rarity":"common","id":"yellowjacket","subtitle":"Villain","details":"Darren Cross, a ruthless weapons executive, weaponized Pym Particle shrinking technology and claimed the Yellowjacket name in his war on Ant-Man.","image":"https://vignette.wikia.nocookie.net/marveldatabase/images/4/4c/Avengers_The_Trial_of_Yellowjacket_TPB_Vol_1_1.jpg/revision/latest/scale-to-width-down/1000?cb=20200430233544"},{"name":"Alfred Pennyworth","rarity":"common","id":"alfred-pennyworth","subtitle":"Supporting","details":"Alfred Pennyworth, the Wayne family's butler since 1943, is Batman's confidant, medic and dry-witted moral compass.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/7/78/Batman_Pennyworth_R.I.P._Vol_1_1_Textless.jpg/revision/latest?cb=20200214161242"},{"name":"Aqualad (Kaldur'ahm)","rarity":"common","id":"aqualad-kaldurahm","subtitle":"Hero","details":"Kaldur'ahm, the son of Black Manta raised in Atlantis, debuted in 2010 as Aqualad, wielding water-bearers and Atlantean sorcery.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/6/63/Aqualad_Jackson_Hyde_0004.jpg/revision/latest/scale-to-width-down/512"},{"name":"Arkham Asylum","rarity":"common","id":"arkham-asylum","subtitle":"Location","details":"Arkham Asylum, Gotham's hospital for the criminally insane, houses the Joker and most of Batman's rogues — rarely for long.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/c0/Arkham_Asylum_003.jpg/revision/latest?cb=20110521045319"},{"name":"Batgirl (Cassandra Cain)","rarity":"common","id":"batgirl-cassandra-cain","subtitle":"Hero","details":"Cassandra Cain, raised by the assassin David Cain without spoken language, debuted in 1999 and became Batgirl through unmatched combat skill.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/d/d3/Batgirl_Cassandra_Cain_0003.jpg/revision/latest?cb=20110523175622"},{"name":"Batgirl (Stephanie Brown)","rarity":"common","id":"batgirl-stephanie-brown","subtitle":"Hero","details":"Stephanie Brown debuted in 1992 as the Spoiler, the Cluemaster's daughter, and later served as both Robin and Batgirl.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/6/6f/Batgirl_Stephanie_Brown_0017.jpg/revision/latest?cb=20130402215751"},{"name":"Big Barda","rarity":"common","id":"big-barda","subtitle":"Hero","details":"Big Barda, raised as Apokolips's top Female Fury, debuted in 1971 and defected to Earth alongside Mister Miracle.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/9/98/Big_Barda_0005.jpg/revision/latest?cb=20240610135246"},{"name":"Blue Beetle (Ted Kord)","rarity":"common","id":"blue-beetle-ted-kord","subtitle":"Hero","details":"Ted Kord debuted in 1966; a genius inventor with no powers who fought crime as the second Blue Beetle with gadgets and wit.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/2/28/Blue_Beetle_Ted_Kord_0001.jpg/revision/latest?cb=20060117032048"},{"name":"Captain Atom","rarity":"common","id":"captain-atom","subtitle":"Hero","details":"Captain Atom is a living nuclear reactor in human form, channeling atomic energy after an Air Force experiment bonded a metal shell to his skin.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/b/be/The_Fall_and_Rise_of_Captain_Atom_Vol_1_4_Textless.jpg/revision/latest?cb=20170402234249"},{"name":"Captain Boomerang","rarity":"common","id":"captain-boomerang","subtitle":"Villain","details":"George 'Digger' Harkness debuted in The Flash #117 in 1960; an Australian rogue whose trick boomerangs plague the Flash.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/45/Captain_Boomerang_0004.jpg/revision/latest?cb=20100415003712"},{"name":"Central City","rarity":"common","id":"central-city","subtitle":"Location","details":"Central City, home of the Flash family, is a Midwestern city of science museums, Rogues and lightning-fast heroes.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/c5/Central_City_001.jpg/revision/latest?cb=20121004104104"},{"name":"Circe","rarity":"common","id":"circe","subtitle":"Villain","details":"Circe, the mythic sorceress who turns men into beasts, first tormented Wonder Woman in Wonder Woman #37 in 1949.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/1/19/Circe_0004.jpg/revision/latest/scale-to-width-down/512"},{"name":"Commissioner Gordon","rarity":"common","id":"commissioner-gordon","subtitle":"Supporting","details":"James Gordon debuted in Detective Comics #27 in 1939; Gotham's police commissioner and Batman's oldest ally.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/d/de/Detective_Comics_Vol_2_25_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Daily Planet","rarity":"common","id":"daily-planet","subtitle":"Location","details":"The Daily Planet, Metropolis's great newspaper, is home to Lois Lane, Clark Kent and Jimmy Olsen beneath its famous globe.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/2/21/Daily_Planet_001.jpg/revision/latest?cb=20110919054553"},{"name":"Deadshot","rarity":"common","id":"deadshot","subtitle":"Villain","details":"Floyd Lawton, known as Deadshot, debuted in Batman #59 in 1950; a marksman who never misses and a Suicide Squad mainstay.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/3/33/Justice_League_of_America_Vol_3_7.1_Deadshot_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Doctor Mid-Nite","rarity":"common","id":"doctor-mid-nite","subtitle":"Hero","details":"Charles McNider, a blind surgeon who can see in darkness, debuted in 1941 as Doctor Mid-Nite, fighting crime with his owl Hooty.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/c1/Charles_McNider_Prime_Earth_002.jpg/revision/latest?cb=20221017070955"},{"name":"Doctor Sivana","rarity":"common","id":"doctor-sivana","subtitle":"Villain","details":"Dr. Thaddeus Sivana, Shazam's mad-scientist nemesis, debuted in Whiz Comics #2 in 1940 alongside the hero himself.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/5/52/Thaddeus_Sivana_Prime_Earth_0001.jpg/revision/latest/scale-to-width-down/512"},{"name":"Enchantress","rarity":"common","id":"enchantress","subtitle":"Villain","details":"June Moone, an artist possessed by an ancient witch, debuted as the Enchantress in Strange Adventures #187 in 1966.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/d/df/Enchantress_0016.jpg/revision/latest?cb=20141204112510"},{"name":"Etrigan","rarity":"common","id":"etrigan","subtitle":"Anti-Hero","details":"Etrigan, a rhyming demon bound to the mortal Jason Blood by Merlin, debuted in The Demon #1 in 1972, created by Jack Kirby.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/4e/Etrigan_0001.jpg/revision/latest?cb=20111001101849"},{"name":"Etta Candy","rarity":"common","id":"etta-candy","subtitle":"Supporting","details":"Etta Candy, Wonder Woman's bold, candy-loving best friend, debuted in Sensation Comics #2 in 1942. Woo woo!","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/1/11/Etta_Candy_Earth-Two_002.jpg/revision/latest?cb=20140403153531"},{"name":"Firestorm","rarity":"common","id":"firestorm","subtitle":"Hero","details":"Firestorm, the nuclear man, debuted in 1978 when student Ronnie Raymond and Professor Martin Stein fused in an atomic accident.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/1/1f/The_Fury_of_Firestorm_Vol_2_1_Textless.png/revision/latest?cb=20260409035314"},{"name":"Fortress of Solitude","rarity":"common","id":"fortress-of-solitude","subtitle":"Location","details":"The Fortress of Solitude, Superman's Arctic sanctuary, holds Kryptonian archives and trophies behind a door only he can open.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/e/ea/Fortress_of_Solitude_modern.JPG/revision/latest?cb=20140508105002"},{"name":"Green Lantern (Alan Scott)","rarity":"common","id":"green-lantern-alan-scott","subtitle":"Hero","details":"Alan Scott, the original Green Lantern, debuted in All-American Comics #16 in 1940, powered by the magic Starheart.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/e/e7/The_New_Golden_Age_Vol_1_1_Textless_Talaski_Variant.jpg/revision/latest?cb=20221116045529"},{"name":"Green Lantern (Jessica Cruz)","rarity":"common","id":"green-lantern-jessica-cruz","subtitle":"Hero","details":"Jessica Cruz, chosen by a power ring in 2014, overcame crippling anxiety to stand as a Green Lantern of Earth.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/e/e8/Green_Lantern_Vol_7_9_Doc_Shaner_Textless_Variant.jpg/revision/latest?cb=20240804095543"},{"name":"Green Lantern (Simon Baz)","rarity":"common","id":"green-lantern-simon-baz","subtitle":"Hero","details":"Simon Baz, a Lebanese-American mechanic wrongly branded a terrorist, debuted in 2012 as a Green Lantern of Earth.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/0/0f/Green_Lantern_Vol_5_16_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Harvey Bullock","rarity":"common","id":"harvey-bullock","subtitle":"Supporting","details":"Harvey Bullock, Gotham's slovenly but loyal detective, debuted in 1974 as one of Commissioner Gordon's top cops.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/b/be/Harvey_Bullock_0001.jpg/revision/latest?cb=20140711182121"},{"name":"Heat Wave","rarity":"common","id":"heat-wave","subtitle":"Villain","details":"Mick Rory, known as Heat Wave, debuted in The Flash #140 in 1963; a pyromaniac Rogue armed with a hand-held flamethrower.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/a6/Heat_Wave_0004.jpg/revision/latest?cb=20160809173150"},{"name":"Hourman","rarity":"common","id":"hourman","subtitle":"Hero","details":"Rex Tyler debuted in 1940 as Hourman; his Miraclo pill grants exactly one hour of super-strength and speed at a time.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/88/Rex_Tyler_Prime_Earth_002.jpg/revision/latest?cb=20240407141933"},{"name":"Injustice League","rarity":"common","id":"injustice-league","subtitle":"Team","details":"The Injustice League is an all-star villain alliance built to mirror and destroy the Justice League, often led by Lex Luthor.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/8c/Forever_Evil_Vol_1_5_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Iris West","rarity":"common","id":"iris-west","subtitle":"Supporting","details":"Iris West, a Central City reporter and Barry Allen's great love, debuted in Showcase #4 in 1956 alongside the Flash.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/81/Iris_West_%28Prime_Earth%29_0004.jpg/revision/latest?cb=20200623175748"},{"name":"Jimmy Olsen","rarity":"common","id":"jimmy-olsen","subtitle":"Supporting","details":"Jimmy Olsen, the Daily Planet's eager photojournalist and Superman's pal, is famous for his signal watch and wild transformations.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/5/51/Jimmy_Olsen_Earth-One_0001.jpg/revision/latest?cb=20260611120949"},{"name":"Jonah Hex","rarity":"common","id":"jonah-hex","subtitle":"Anti-Hero","details":"Jonah Hex, a scarred Confederate veteran turned bounty hunter, debuted in 1972; the Wild West's deadliest shot.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/44/All-Star_Western_Vol_3_0_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Jonathan Kent","rarity":"common","id":"jonathan-kent","subtitle":"Supporting","details":"Jonathan Kent, the Kansas farmer who raised Clark Kent, taught the future Superman honesty, humility and hard work.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/ae/The_Man_of_Steel_Vol_2_2_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Killer Frost","rarity":"common","id":"killer-frost","subtitle":"Villain","details":"Killer Frost is a heat vampire who freezes all she touches; the name has passed from Crystal Frost to Caitlin Snow since 1978.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/7/77/Justice_League_of_America_Killer_Frost_Rebirth_Vol_1_1_Textless_Variant.jpg/revision/latest?cb=20170129033443"},{"name":"King Shark","rarity":"common","id":"king-shark","subtitle":"Villain","details":"King Shark, or Nanaue, a humanoid shark claiming descent from a shark god, debuted in Superboy #0 in 1994.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/80/Aquaman_Vol_8_32_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Kite Man","rarity":"common","id":"kite-man","subtitle":"Villain","details":"Kite Man, or Charles Brown, debuted in Batman #133 in 1960; a kite-riding crook whose catchphrase is 'Hell yeah.'","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/f/f6/Kite-Man_PE_01.jpg/revision/latest/scale-to-width-down/1200?cb=20160909043905"},{"name":"Lady Shiva","rarity":"common","id":"lady-shiva","subtitle":"Villain","details":"Lady Shiva, one of the world's deadliest martial artists, debuted in 1975 and has both trained and hunted Batman himself.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/b/ba/Sandra_Wu-San_Prime_Earth_004.jpg/revision/latest/scale-to-width-down/512"},{"name":"Lana Lang","rarity":"common","id":"lana-lang","subtitle":"Supporting","details":"Lana Lang, Clark Kent's Smallville sweetheart and longtime confidante, debuted in Superboy #10 in 1950.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/0/0c/Superwoman_Vol_1_10_Textless.jpg/revision/latest/scale-to-width-down/512"},{"name":"Larfleeze","rarity":"common","id":"larfleeze","subtitle":"Villain","details":"Larfleeze, sole keeper of the orange light of avarice, is a hoarder billions of years old who claims everything as 'mine!'","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/9/93/Agent_Orange.JPG/revision/latest?cb=20140406121828"},{"name":"Leslie Thompkins","rarity":"common","id":"leslie-thompkins","subtitle":"Supporting","details":"Dr. Leslie Thompkins debuted in Detective Comics #457 in 1976; a pacifist physician who treats Gotham's wounded, even criminals.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/2/2a/Leslie_Thompkins_1.jpg/revision/latest?cb=20080516140318"},{"name":"Linda Park","rarity":"common","id":"linda-park","subtitle":"Supporting","details":"Linda Park, a reporter who debuted in 1989, became Wally West's wife and the lightning rod that guides him home.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/b/b7/Linda_Park_001.jpg/revision/latest?cb=20120302021147"},{"name":"Lois Lane","rarity":"common","id":"lois-lane","subtitle":"Supporting","details":"Lois Lane, the Daily Planet's fearless star reporter, debuted alongside Superman in Action Comics #1 in 1938.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/ca/Lois_Lane_Vol_2_7_Variant_Textless.jpg/revision/latest?cb=20200110172538"},{"name":"Lucius Fox","rarity":"common","id":"lucius-fox","subtitle":"Supporting","details":"Lucius Fox debuted in Batman #307 in 1979; Wayne Enterprises' CEO and the quiet source of Batman's technology.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/3/35/Lucius_Fox_0001.jpg/revision/latest?cb=20111011224319"},{"name":"Martha Kent","rarity":"common","id":"martha-kent","subtitle":"Supporting","details":"Martha Kent found and raised the infant Kal-El in Smallville, grounding Superman's humanity in Kansas farm values.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/4d/Martha_Kent_0001.jpg/revision/latest?cb=20100103204236"},{"name":"Mirror Master","rarity":"common","id":"mirror-master","subtitle":"Villain","details":"Mirror Master, a Flash rogue since The Flash #105 in 1959, travels and strikes through any reflective surface.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/aa/Samscudder.jpg/revision/latest?cb=20200527025205"},{"name":"Mister Miracle","rarity":"common","id":"mister-miracle","subtitle":"Hero","details":"Scott Free, Highfather's son raised on Apokolips, debuted in 1971 as Mister Miracle, the universe's greatest escape artist.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/ab/Mister_Miracle_Scott_Free_0003.jpg/revision/latest?cb=20091029025125"},{"name":"Mr. Mind","rarity":"common","id":"mr-mind","subtitle":"Villain","details":"Mister Mind, a tiny worm from Venus with a genius intellect, debuted in 1943 as one of Shazam's strangest foes.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/cf/Mister_Mind_%28New_Earth%29_003.jpg/revision/latest?cb=20110620000812"},{"name":"Mr. Mxyzptlk","rarity":"common","id":"mr-mxyzptlk","subtitle":"Villain","details":"Mr. Mxyzptlk, a fifth-dimensional imp who debuted in 1944, torments Superman with reality-warping pranks; saying his name backwards banishes him.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/a9/Mister_Mxyzptlk_001.jpg/revision/latest?cb=20091104040525"},{"name":"Mr. Terrific","rarity":"common","id":"mr-terrific","subtitle":"Hero","details":"Michael Holt, an Olympic decathlete and genius inventor, debuted in 1997 as Mr. Terrific, billed as the world's third smartest man.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/cd/Mister_Terrific_Michael_Holt_0001.jpg/revision/latest?cb=20161019190100"},{"name":"Orion","rarity":"common","id":"orion","subtitle":"Hero","details":"Orion, Darkseid's son traded to New Genesis in a peace pact, debuted in 1971 as the Dog of War, fighting his own inner rage.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/f/ff/Orion_009.jpg/revision/latest?cb=20100413202701"},{"name":"Outsiders","rarity":"common","id":"outsiders","subtitle":"Team","details":"The Outsiders, Batman's covert strike team, debuted in 1983 when he quit the League to lead heroes who work in shadow.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/6/63/Outsiders_0021.jpg/revision/latest?cb=20140801174732"},{"name":"Perry White","rarity":"common","id":"perry-white","subtitle":"Supporting","details":"Perry White, the Daily Planet's gruff editor-in-chief, is known for barking 'Great Caesar's ghost!' at his staff.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/3/30/Perry_White_0003.jpg/revision/latest?cb=20091018064655"},{"name":"Power Girl","rarity":"common","id":"power-girl","subtitle":"Hero","details":"Power Girl, Kara Zor-L of Earth-Two, debuted in All Star Comics #58 in 1976; Superman's cousin from a parallel world.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/0/09/Power_Girl_Vol_3_1_Variant_3_Textless.jpg/revision/latest?cb=20230926095833"},{"name":"Queen Hippolyta","rarity":"common","id":"queen-hippolyta","subtitle":"Supporting","details":"Queen Hippolyta, ruler of the Amazons and Wonder Woman's mother, debuted in 1941; in the original tale she sculpted Diana from clay.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/7/7f/Hippolyta_0001.jpg/revision/latest?cb=20091023150612"},{"name":"Renee Montoya","rarity":"common","id":"renee-montoya","subtitle":"Supporting","details":"Renee Montoya, a Gotham detective who debuted in Batman: The Animated Series in 1992, later inherited the Question's mantle.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/48/Question_RM_01.jpg/revision/latest?cb=20160303213657"},{"name":"Rick Flag","rarity":"common","id":"rick-flag","subtitle":"Supporting","details":"Rick Flag, the Suicide Squad's field leader, debuted in The Brave and the Bold #25 in 1959; a soldier among criminals.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/87/Rick_Flag_Jr_0009.jpg/revision/latest?cb=20141112145317"},{"name":"Sandman (Wesley Dodds)","rarity":"common","id":"sandman-wesley-dodds","subtitle":"Hero","details":"Wesley Dodds debuted in 1939 as the Sandman, a gas-masked detective armed with a sleeping-gas gun and prophetic dreams.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/cd/Wesley_Dodds_0001.jpg/revision/latest?cb=20130713132933"},{"name":"Sgt. Rock","rarity":"common","id":"sgt-rock","subtitle":"Hero","details":"Sgt. Frank Rock, leader of Easy Company, debuted in 1959; DC's quintessential World War II infantryman, armed with grit alone.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/c2/Sgt_Rock_01.jpg/revision/latest?cb=20080831051838"},{"name":"Star Sapphire (Carol Ferris)","rarity":"common","id":"star-sapphire-carol-ferris","subtitle":"Villain","details":"Carol Ferris debuted in 1959 and became Star Sapphire, wielder of a violet ring powered by love, both foe and flame of Hal Jordan.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/cc/Star_Sapphire_008.jpg/revision/latest?cb=20110303024250"},{"name":"Steve Trevor","rarity":"common","id":"steve-trevor","subtitle":"Supporting","details":"Steve Trevor, the pilot whose crash onto Themyscira brought Wonder Woman to man's world, debuted alongside her in 1941.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/8/8f/Steve_Trevor_0005.png/revision/latest?cb=20231231175904"},{"name":"Talia al Ghul","rarity":"common","id":"talia-al-ghul","subtitle":"Villain","details":"Talia al Ghul, daughter of Ra's al Ghul, debuted in Detective Comics #411 in 1971; assassin, heir and mother of Damian Wayne.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/cb/Talia_al_Ghul_0009.jpg/revision/latest?cb=20110527020201"},{"name":"The Flash (Jay Garrick)","rarity":"common","id":"the-flash-jay-garrick","subtitle":"Hero","details":"Jay Garrick, the original Flash, debuted in Flash Comics #1 in 1940 after inhaling hard-water vapors in his lab.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/c/c2/Flash_Jay_Garrick_0002.jpg/revision/latest?cb=20100510161228"},{"name":"The Trickster","rarity":"common","id":"the-trickster","subtitle":"Villain","details":"The Trickster, James Jesse, debuted in The Flash #113 in 1960; a con man whose deadly gag gadgets torment the Flash.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/1/19/Trickster_0004.jpg/revision/latest?cb=20121107083954"},{"name":"Toyman","rarity":"common","id":"toyman","subtitle":"Villain","details":"Winslow Schott, the Toyman, debuted in Action Comics #64 in 1943, building deadly toys to torment Superman.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/b/b8/Toyman_002.jpg/revision/latest?cb=20091015233650"},{"name":"Vicki Vale","rarity":"common","id":"vicki-vale","subtitle":"Supporting","details":"Vicki Vale, a Gotham Gazette reporter, debuted in Batman #49 in 1948, forever close to uncovering Batman's secret.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/4/49/Vicki_Vale_0030.jpeg/revision/latest?cb=20260527004827"},{"name":"Watchtower","rarity":"common","id":"watchtower","subtitle":"Location","details":"The Watchtower, the Justice League's orbital headquarters, watches over Earth from space with teleporters and a trophy hall.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/a/a2/Justice_League_Watchtower_001.jpg/revision/latest?cb=20090606194319"},{"name":"Wildcat","rarity":"common","id":"wildcat","subtitle":"Hero","details":"Ted Grant, a heavyweight boxer turned Wildcat, debuted in Sensation Comics #1 in 1942 and trained generations of heroes.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/e/ed/Wildcat_0002.jpg/revision/latest?cb=20200522121935"},{"name":"Young Justice","rarity":"common","id":"young-justice","subtitle":"Team","details":"Young Justice, a junior hero team formed in 1998 around Robin, Superboy and Impulse, takes the missions the League cannot.","image":"https://vignette.wikia.nocookie.net/marvel_dc/images/f/f6/Young_Justice_0001.jpg/revision/latest?cb=20140808172001"},{"name":"Allison Hargreeves","rarity":"common","id":"allison-hargreeves","subtitle":"Hero","details":"The Rumor: Allison reshapes reality by lying — 'I heard a rumor' — a power that costs her voice, her marriage and her daughter's trust.","image":"https://cdn.media.amplience.net/s/hottopic/36265341_hi?h=630"},{"name":"Archer & Armstrong","rarity":"common","id":"archer-and-armstrong","subtitle":"Team","details":"Valiant's odd couple: immortal, hard-drinking Armstrong and Obadiah Archer, the naive martial-arts prodigy raised by a doomsday sect.","image":"https://comicsexperience.com/wp-content/uploads/2020/01/Archer_and_Armstrong_Vol_2_1.webp"},{"name":"Arthur","rarity":"common","id":"arthur","subtitle":"Supporting","details":"The Tick's mild-mannered sidekick, a former accountant in a moth suit, Arthur supplies the common sense his invulnerable partner cheerfully lacks.","image":"assets/sets/compress/hero-additions__arthur.webp"},{"name":"B.P.R.D.","rarity":"common","id":"bprd","subtitle":"Team","details":"The Bureau for Paranormal Research and Defense sends agents like Hellboy and Abe Sapien to investigate and battle occult threats worldwide.","image":"https://d2lzb5v10mb0lj.cloudfront.net/covers/400/15/15990.jpg"},{"name":"Billy Cranston (Blue Ranger)","rarity":"common","id":"billy-cranston-blue-ranger","subtitle":"Hero","details":"The original Blue Ranger and the team's genius, Billy Cranston builds the gadgets and communicators that keep the Mighty Morphin Rangers fighting.","image":"https://images.squarespace-cdn.com/content/v1/5d51bb507fc57e000122d8df/1587441097485-CZ9VMH67W692XLRWUUU2/MMPRMorpher-BillyBlue.jpg?format=1000w"},{"name":"Casey Jones","rarity":"common","id":"casey-jones","subtitle":"Anti-Hero","details":"A hockey-masked vigilante who metes out street justice with bats, clubs and golf bags, Casey Jones is the Turtles' closest human ally in a fight.","image":"assets/sets/compress/hero-additions__casey-jones.webp"},{"name":"Cecil Stedman","rarity":"common","id":"cecil-stedman","subtitle":"Supporting","details":"The scarred director of the Global Defense Agency, who funds, monitors and ruthlessly deploys Earth's heroes in Image's Invincible.","image":"https://ovicio.com.br/wp-content/uploads/2021/05/20210515-cecil03.png"},{"name":"Cogliostro","rarity":"common","id":"cogliostro","subtitle":"Supporting","details":"A mysterious drifter who mentors Spawn; secretly Cain, the first murderer, bound to Hell after his own ancient bargain with Malebolgia.","image":"https://todd.mcfarlane.com/wp-content/uploads/2015/05/spawn_comic_cover_083_cl.jpg"},{"name":"Debbie Grayson","rarity":"common","id":"debbie-grayson","subtitle":"Supporting","details":"Mark's mother and Nolan's wife, whose discovery of her husband's true Viltrumite mission shatters — and then rebuilds — the Grayson family.","image":"https://vignette.wikia.nocookie.net/comic-invincible/images/1/17/Debbie.png/revision/latest/scale-to-width-down/512"},{"name":"Diego Hargreeves","rarity":"common","id":"diego-hargreeves","subtitle":"Hero","details":"The Kraken: Diego can curve the trajectory of anything he throws, making his knives unerring; a rebellious, knife-first Umbrella Academy hero.","image":"https://static0.cbrimages.com/wordpress/wp-content/uploads/2017/07/umbrella-academy-02.jpg?q=50&fit=crop&w=825&dpr=1.5"},{"name":"Dupli-Kate","rarity":"common","id":"dupli-kate","subtitle":"Hero","details":"Kate Cha can generate endless copies of herself, sending duplicates into danger while her original body stays safely out of harm's way.","image":"https://vignette.wikia.nocookie.net/imagecomics/images/1/1f/Duplikate.jpg/revision/latest?cb=20070226232540"},{"name":"Eternal Warrior","rarity":"common","id":"eternal-warrior","subtitle":"Hero","details":"Gilad Anni-Padda has fought in every war for over 6,000 years, an immortal tactician bound to protect the Geomancers in Valiant's universe.","image":"https://assets.comic-odyssey.com/products/covers/000/103/273/original/open-uri20240913-2-1ctmre5?1726270728"},{"name":"Grendel","rarity":"common","id":"grendel","subtitle":"Anti-Hero","details":"Hunter Rose, a brilliant author and assassin, builds a criminal empire as the masked Grendel — a mantle later claimed by far darker successors.","image":"https://pixelatedgeek.com/wp-content/uploads/2021/12/GrendelOmnibus.jpg"},{"name":"Guardians of the Globe","rarity":"common","id":"guardians-of-the-globe","subtitle":"Team","details":"Earth's premier superhero team in Image's Invincible, rebuilt under Robot and the Immortal after Omni-Man murders the original lineup.","image":"assets/sets/compress/hero-additions__guardians-of-the-globe.webp"},{"name":"Johann Kraus","rarity":"common","id":"johann-kraus","subtitle":"Hero","details":"A German medium whose body was destroyed by an astral disaster, Johann Kraus survives as ectoplasm sealed inside a B.P.R.D. containment suit.","image":"https://alchetron.com/cdn/johann-kraus-107a8aa6-e12f-485b-bde4-17271c719c3-resize-750.jpeg"},{"name":"Judge Anderson","rarity":"common","id":"judge-anderson","subtitle":"Hero","details":"Judge Cassandra Anderson of Psi Division reads minds and battles psychic threats in Mega-City One, 2000 AD's empathic counterpoint to Dredd.","image":"assets/sets/compress/hero-additions__judge-anderson.webp"},{"name":"Karai","rarity":"common","id":"karai","subtitle":"Anti-Hero","details":"A high-ranking Foot Clan warrior raised by Shredder, Karai walks a line between honor and ambition that sometimes makes her the Turtles' ally.","image":"https://static1.cbrimages.com/wordpress/wp-content/uploads/2017/04/TMNT-Universe12-cvrRI-copy.jpg"},{"name":"Karl Ruprecht Kroenen","rarity":"common","id":"karl-ruprecht-kroenen","subtitle":"Villain","details":"A clockwork-obsessed Nazi scientist of Project Ragna Rok, Kroenen's gas mask and wind-up blades make him one of Hellboy's eeriest foes.","image":"https://i.pinimg.com/736x/b8/91/b0/b891b00f85135834b4719195f530cc0f--graphic-novel-karl.jpg"},{"name":"Kato","rarity":"common","id":"kato","subtitle":"Supporting","details":"The Green Hornet's chauffeur and partner, Kato is a martial-arts master and engineering genius — the muscle behind the Black Beauty's wheel.","image":"https://iv1.lisimg.com/image/16096582/600full-kato-cover.jpg"},{"name":"Kid Omni-Man","rarity":"common","id":"kid-omni-man","subtitle":"Hero","details":"Oliver Grayson, Invincible's fast-aging younger half-brother, takes the name Kid Omni-Man and fights beside Mark despite his Viltrumite roots.","image":"https://i.pinimg.com/originals/5b/32/a0/5b32a0c2b6113b93c9192265510957d8.jpg"},{"name":"Kimberly Hart (Pink Ranger)","rarity":"common","id":"kimberly-hart-pink-ranger","subtitle":"Hero","details":"The original Pink Ranger, gymnast Kimberly Hart pilots the Pterodactyl Zord and fights with the Power Bow in the Mighty Morphin Power Rangers.","image":"assets/sets/compress/hero-additions__kimberly-hart-pink-ranger.webp"},{"name":"Livewire (Amanda McKee)","rarity":"common","id":"livewire-amanda-mckee","subtitle":"Hero","details":"Amanda McKee, Valiant's premier technopath, can seize control of any machine with her mind; a Harbinger ally who once shut down the world's tech.","image":"https://www.comicsbeat.com/wp-content/uploads/2018/11/LIVEWIRE_002_COVER-A_POLLINA.jpg"},{"name":"Luther Hargreeves","rarity":"common","id":"luther-hargreeves","subtitle":"Hero","details":"Spaceboy, the super-strong first Hargreeves child, Luther's desperate bid to impress his father leaves him part ape-bodied in Umbrella Academy.","image":"https://cdn.media.amplience.net/s/hottopic/36265343_hi?h=630"},{"name":"Malebolgia","rarity":"common","id":"malebolgia","subtitle":"Villain","details":"The demon lord of the Eighth Circle of Hell who strikes the bargain that resurrects Al Simmons as Spawn, grooming him to lead Hell's army.","image":"https://comicbook.com/wp-content/uploads/sites/4/2025/07/Malebolgia-Spawn-Image-Comics.jpg"},{"name":"Monster Girl","rarity":"common","id":"monster-girl","subtitle":"Hero","details":"Cursed to transform into a hulking monster, Amanda ages backwards with each change, leaving her adult mind trapped in a child's body.","image":"https://vignette.wikia.nocookie.net/invincible/images/7/70/Monster_Girl.jpg/revision/latest?cb=20130223165012&path-prefix=cs"},{"name":"Rai","rarity":"common","id":"rai","subtitle":"Hero","details":"The guardian spirit of a futuristic Japan in the year 4001, Rai is a nanite-infused warrior created to defend the nation — and question its rulers.","image":"https://valiantentertainment.com/wp-content/uploads/2019/11/RAI_04_COVER-A.jpg"},{"name":"Shadowman","rarity":"common","id":"shadowman","subtitle":"Anti-Hero","details":"Jack Boniface inherits the Shadow Loa's power, crossing into the Deadside to protect New Orleans as Valiant's dark, voodoo-touched Shadowman.","image":"https://brutalgamer.com/wp-content/uploads/2013/07/SM_008_COVER_ZIRCHER.jpg"},{"name":"Tank Girl","rarity":"common","id":"tank-girl","subtitle":"Anti-Hero","details":"A tank-driving outlaw roaming a post-apocalyptic Australia with her mutant kangaroo boyfriend Booga, in Jamie Hewlett and Alan Martin's punk saga.","image":"https://jamiehewlett.com/cdn/shop/files/TankGirl.oe.2-_1_2.jpg?v=1750174236&width=1500"},{"name":"The Crow","rarity":"common","id":"the-crow","subtitle":"Anti-Hero","details":"Eric Draven returns from the grave one year after his murder, guided by a crow, to avenge himself and his fiancée in James O'Barr's gothic tale.","image":"https://img2.safereactor.cc/pics/post/The-Crow-Comic-Books-%D1%84%D1%8D%D0%BD%D0%B4%D0%BE%D0%BC%D1%8B-3344710.jpeg"},{"name":"The Goon","rarity":"common","id":"the-goon","subtitle":"Anti-Hero","details":"A hulking enforcer in a zombie-infested town, Eric Powell's Goon settles debts with his fists alongside his foul-mouthed partner Franky.","image":"https://i1.whakoom.com/large/01/35/fa389ea5df644b0c8f064267c8ba33b0.jpg"},{"name":"The Phantom","rarity":"common","id":"the-phantom","subtitle":"Hero","details":"The Ghost Who Walks: for centuries, fathers have passed the Phantom's mantle and oath — to fight piracy, greed and injustice — to their sons.","image":"https://static0.cbrimages.com/wordpress/wp-content/uploads/covers/KingPhantom01-Cov-A-CookeCol.jpg"},{"name":"The Rocketeer","rarity":"common","id":"the-rocketeer","subtitle":"Hero","details":"In 1938 Los Angeles, stunt pilot Cliff Secord finds a stolen jetpack and becomes the Rocketeer, pursued by gangsters, spies and the FBI alike.","image":"https://i0.wp.com/comicon.com/wp-content/uploads/2023/01/5057be19-2cec-4a1f-8504-15d4147291c9.jpg?resize=675%2C1024&ssl=1"},{"name":"Trini Kwan (Yellow Ranger)","rarity":"common","id":"trini-kwan-yellow-ranger","subtitle":"Hero","details":"The original Yellow Ranger, Trini Kwan is the team's calm, compassionate heart and a precise martial artist piloting the Sabertooth Tiger Zord.","image":"https://images.squarespace-cdn.com/content/v1/5d51bb507fc57e000122d8df/1587441112084-17N564VJ9HG0XGXX7RJ4/MMPRMorpher-TriniYellow.jpg?format=1000w"},{"name":"Vampirella","rarity":"common","id":"vampirella","subtitle":"Anti-Hero","details":"A vampire from the dying planet Drakulon, Vampirella feeds on the blood of the wicked and hunts the monsters that prey on humanity.","image":"https://comic-watch.com/wp-content/uploads/2019/07/Vampirella50th-001-Cov-01261-01501-compressed-19.jpg"},{"name":"Viktor Hargreeves","rarity":"common","id":"viktor-hargreeves","subtitle":"Anti-Hero","details":"Dismissed as powerless, Viktor is secretly the White Violin, whose sound-based powers can crack the Moon — the family's hidden apocalypse.","image":"https://static1.srcdn.com/wordpress/wp-content/uploads/2024/08/the-umbrella-academy-comic-vanya-as-the-white-violin.jpg"},{"name":"Zack Taylor (Black Ranger)","rarity":"common","id":"zack-taylor-black-ranger","subtitle":"Hero","details":"The original Black Ranger, Zack Taylor blends breakdancing with martial arts in his Hip-Hop Kido style and pilots the Mastodon Zord.","image":"https://rangercommand.com/wp-content/uploads/2022/06/ChargeTo100_MMPR100_MiguelMercado_CharacterDesigns_Zack_PROMO-1.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
